import{_ as t,a as n,b as r,c as i}from"./chunks/package-import-297.C0Lrc5sP.js";import{_ as a,o as s,c as d,a3 as l}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Geräte und Tablet","description":"Geräte-Kacheln, Grundriss-Marker, Tablet-Rückkehr und Paketfähigkeiten ab Studio 0.1.297.","frontmatter":{"title":"Geräte und Tablet","description":"Geräte-Kacheln, Grundriss-Marker, Tablet-Rückkehr und Paketfähigkeiten ab Studio 0.1.297."},"headers":[],"relativePath":"projects/grafik-visual-studio/devices-tablet.md","filePath":"projects/grafik-visual-studio/devices-tablet.md","lastUpdated":1794146905000}'),o={name:"projects/grafik-visual-studio/devices-tablet.md"};function u(h,e,g,c,b,k){return s(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="gerate-und-tablet" tabindex="-1">Geräte und Tablet <a class="header-anchor" href="#gerate-und-tablet" aria-label="Permalink to &quot;Geräte und Tablet&quot;">​</a></h1><p>Ab <strong>Studio 0.1.297</strong> enthält die Palette das integrierte Set <strong>Geräte</strong>. Keine zusätzliche Paketinstallation erforderlich. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.297" target="_blank" rel="noreferrer">GitHub-Update</a>.</p><h2 id="gerate-hinzufugen" tabindex="-1">Geräte hinzufügen <a class="header-anchor" href="#gerate-hinzufugen" aria-label="Permalink to &quot;Geräte hinzufügen&quot;">​</a></h2><p>Das Set aufklappen, ein Widget auf die Editorfläche ziehen und in den Eigenschaften die HA-Entität auswählen. <strong>Schalter, Dimmer, farbiges Licht, Thermostat und Messwert</strong> stehen jeweils als <strong>Kachel</strong> und <strong>Grundriss-Marker mit Popup</strong> bereit: insgesamt zehn Einträge. Position und Größe sind frei einstellbar; dies ist kein automatisches responsives Raster. Die fünf Standard-CSS-Gruppen stehen zur Verfügung, neue optionale Gruppen bleiben deaktiviert. Widget-Sprache: DE/EN/FR, allgemeine Studio-Oberfläche: DE/EN.</p><p><img src="'+t+'" alt="Geräte-Kacheln und Grundriss-Marker, lokale Demo"></p><table tabindex="0"><thead><tr><th>Widget</th><th>Quelle und Bedienung</th></tr></thead><tbody><tr><td>Schalter</td><td><code>switch</code>, <code>light</code> oder <code>input_boolean</code>; ein/aus</td></tr><tr><td>Dimmer</td><td><code>light</code>; Helligkeit nur bei passender HA-Fähigkeit</td></tr><tr><td>Farbiges Licht</td><td><code>light</code>; ein/aus, Helligkeit und RGB je nach unterstütztem Farbmodus</td></tr><tr><td>Thermostat</td><td><code>climate</code>; einzelner Temperatursollwert innerhalb nativer Grenzen/Schrittweite</td></tr><tr><td>Messwert</td><td>Zustand und Einheit; ausschließlich lesend</td></tr></tbody></table><p>Die Runtime bietet nur von der Entität unterstützte Bedienelemente an. <strong>Nur lesen</strong> sperrt Schreibaktionen. Im Editor werden keine Geräte geschaltet; nicht verfügbare Entitäten sind deaktiviert. Die Serverprüfung bleibt aktiv. Eine angenommene Anfrage ist noch keine physische Gerätebestätigung. Für erweiterte Climate-Funktionen wie Temperaturbereiche weiterhin <a href="./ha-quellen-climate">Technic/Climate</a> verwenden.</p><h2 id="tablet-ruckkehr-und-startseite" tabindex="-1">Tablet-Rückkehr und Startseite <a class="header-anchor" href="#tablet-ruckkehr-und-startseite" aria-label="Permalink to &quot;Tablet-Rückkehr und Startseite&quot;">​</a></h2><p>Unter <strong>Einstellungen → Allgemein</strong> aktualisiert <strong>Zustände bei Tablet-Rückkehr aktualisieren</strong> die HA-Werte beim Wiederanzeigen, bei Seitenwiederherstellung und nach erneuter Netzwerkverbindung. Die gesamte Seite wird dafür nicht neu geladen. Browser/Tablet dürfen ihre Timer im Hintergrund aussetzen; beim Zurückkehren wird dies berücksichtigt.</p><p><strong>Startseite nach Inaktivität</strong> und <strong>Inaktivitäts-Startseite</strong> bestimmen Zeit und sichtbare Zielseite im aktuellen Projekt. <strong>0 Sekunden = aus</strong> und bleibt die Voreinstellung. Offene Dialoge, laufende Schreibaktionen und aktive Bearbeitung verschieben die automatische Navigation. Keine Kiosk- oder Zugriffsrechte werden verändert.</p><p><img src="'+n+'" alt="Geräteansicht bei 1280 × 800, lokale Demo"></p><p><img src="'+r+'" alt="Licht-Popup auf dem Tablet, lokale Demo"></p><h2 id="live-werte-in-uberschriften" tabindex="-1">Live-Werte in Überschriften <a class="header-anchor" href="#live-werte-in-uberschriften" aria-label="Permalink to &quot;Live-Werte in Überschriften&quot;">​</a></h2><p>Rahmen- und Geräteüberschriften können optional einen HA-Zustand oder ein Attribut mit Nachkommastellen und Einheit anzeigen. Entität und gegebenenfalls Attribut in der entsprechenden Eigenschaftsgruppe wählen. Bestehende Überschriften bleiben erhalten; HA-Werte werden als Text eingefügt.</p><h2 id="renderer-und-paketfahigkeiten" tabindex="-1">Renderer und Paketfähigkeiten <a class="header-anchor" href="#renderer-und-paketfahigkeiten" aria-label="Permalink to &quot;Renderer und Paketfähigkeiten&quot;">​</a></h2><p>Geräte, Wetter, Heizräume, Fensterübersicht, Vermieterbenachrichtigung, Technic-Statusliste und Material-Farbschemata laden ihre Renderer bei Bedarf. Gemeinsame Editor-Module bleiben normal geladen. Gleichzeitige Anforderungen verwenden denselben Ladevorgang.</p><p>Installierte Paketmanifeste werden alle <strong>30 Sekunden</strong> und bei Rückkehr geprüft. Änderungen aktualisieren die Palette ohne Neustart. Dies installiert keine angebotenen Katalog-Updates automatisch. Fehlerhafte Ersetzungen behalten den bisherigen Katalog; entfernte Definitionen bleiben für bereits offene Projekte im Speicher, aber stehen nicht mehr für neue Widgets in der Palette. Projekte werden nicht automatisch migriert. Siehe <a href="./widget-pakete">Paketinstallation</a>.</p><p><code>optionalCapabilities</code> im Manifest ist ein freiwilliger Hinweis: <code>entity-state</code>, <code>history</code>, <code>light-color</code>, <code>climate</code>. Die Paketliste zeigt unterstützt/nicht unterstützt. Unbekannte Fähigkeiten erteilen keine Berechtigungen. Alte Manifeste bleiben gültig; tatsächliche Steuerung hängt weiterhin von HA und den jeweiligen Entitätsfähigkeiten ab.</p><p><img src="'+i+'" alt="Paketimport mit zwei Widgets und Fähigkeitsanzeige auf .177"></p><h2 id="prufung-und-grenzen" tabindex="-1">Prüfung und Grenzen <a class="header-anchor" href="#prufung-und-grenzen" aria-label="Permalink to &quot;Prüfung und Grenzen&quot;">​</a></h2><p>Am <strong>8. November 2026</strong> auf <strong>.177 / HA 2026.11.0 / Raspberry Pi 5 ARM64</strong> und <strong>.193 / HA 2026.10.4 / Proxmox amd64</strong> geprüft: Projekt speichern/erneut laden, tatsächliches Schalten eines temporären HA-Helfers mit Rückmeldung sowie Inaktivitäts-Rückkehr. Auf .177 zusätzlich Marker-Dialog und manueller lokaler Paketimport 1.1.0 mit zwei Widgets und Fähigkeitsanzeige. Testpaket und Testhelfer danach entfernt; Inaktivität wieder auf 0 Sekunden. Studio bleibt auf beiden Systemen installiert, bestehende Projekte/Einstellungen erhalten.</p><p>Helligkeit, RGB und Thermostat wurden mit lokalen simulierten Entitäten geprüft. Die neuen Ansichten wurden im Desktop-Browser bei 1440 × 1000 und mit Tablet-Ansicht 1280 × 800 kontrolliert. Das bestätigt keinen Test auf echter Tablet-Hardware oder mit jedem Lampen-/Heizungstyp. 394 JavaScript- und 109 Python-Prüfungen bestanden; ergänzend 7 gezielte JavaScript- und 17 Paket-Python-Prüfungen. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/devices-tablet-0.1.297.md" target="_blank" rel="noreferrer">Technischer Prüfbericht</a>.</p><p>Eigenständige HA-Umsetzung ohne übernommenen VIS-2-Code oder -Grafiken. Web Components und ein responsiver Rastercontainer bleiben getrennte Folgevorhaben.</p>',23)])])}const v=a(o,[["render",u]]);export{f as __pageData,v as default};
